import React, { useState } from "react";
import StructuredForm from "./StructuredForm/StructuredForm";
import ChatWindow from "./ChatInterface/ChatWindow";
import InteractionList from "./InteractionList";

export default function LogInteractionScreen() {
  const [mode, setMode] = useState("form"); // "form" | "chat"

  return (
    <div className="app-container">
      <div className="header">
        <h2>HCP — Log Interaction</h2>
      </div>

      <div className="mode-toggle">
        <button
          className={mode === "form" ? "active" : ""}
          onClick={() => setMode("form")}
        >
          Structured Form
        </button>
        <button
          className={mode === "chat" ? "active" : ""}
          onClick={() => setMode("chat")}
        >
          Chat with AI
        </button>
      </div>

      {mode === "form" ? <StructuredForm /> : <ChatWindow />}

      <InteractionList />
    </div>
  );
}
